/**
 * fix-descriptions.mjs
 * Corrige les descriptions génériques "وصفة X تقليدية: Y" en descriptions SEO
 * Usage : node .github/scripts/fix-descriptions.mjs
 */
import fs from 'fs';
import path from 'path';

const HTML_PATH = path.resolve(process.cwd(), 'index.html');
let html = fs.readFileSync(HTML_PATH, 'utf8');

// Patterns de remplacement par zone
const AREA_DESC = {
  'مغربي':   (n) => `وصفة مغربية أصيلة بنكهة ${n} مع التوابل العطرية والمكونات الطازجة`,
  'مصري':    (n) => `طبق مصري شعبي من ${n} بالنكهات التقليدية والمكونات المحلية الأصيلة`,
  'إيطالي':  (n) => `وصفة إيطالية كلاسيكية لطبق ${n} بأجود المكونات والنكهات الأصيلة`,
  'ياباني':  (n) => `طبق ياباني تقليدي من ${n} بالنكهات الآسيوية الفريدة والمكونات الطازجة`,
  'هندي':    (n) => `وصفة هندية شهية بنكهة ${n} مع مزيج البهارات والعطور الشرقية`,
  'صيني':    (n) => `وصفة صينية أصيلة من ${n} بالصلصات العطرية والمكونات التقليدية`,
  'فرنسي':   (n) => `طبق فرنسي كلاسيكي من ${n} بالتقنيات والمكونات الفرنسية الفاخرة`,
  'أمريكي':  (n) => `وصفة أمريكية شهيرة من ${n} بالنكهات الغنية والمكونات المميزة`,
  'بريطاني': (n) => `طبق بريطاني تقليدي من ${n} بالنكهات الكلاسيكية والأسلوب الإنجليزي`,
  'إسباني':  (n) => `وصفة إسبانية أصيلة من ${n} بالنكهات المتوسطية والمكونات الطازجة`,
  'يوناني':  (n) => `طبق يوناني تقليدي من ${n} بالأعشاب المتوسطية والمكونات الطازجة`,
  'تركي':    (n) => `وصفة تركية شهية من ${n} بالبهارات العثمانية والنكهات الشرقية`,
  'لبناني':  (n) => `طبق لبناني أصيل من ${n} بالنكهات الشامية والمكونات الطازجة`,
  'تايلاندي':(n) => `وصفة تايلاندية شهية من ${n} بالأعشاب العطرية وجوز الهند`,
  'مكسيكي':  (n) => `طبق مكسيكي تقليدي من ${n} بالتوابل الحارة والنكهات الأصيلة`,
};

// Regex pour "وصفة X تقليدية: Name"
const generic = /وصفة ([^\s"]+) تقليدية: ([^"]+)/g;

let fixed = 0;
html = html.replace(generic, (match, area, name) => {
  const fn = AREA_DESC[area];
  if (fn) { fixed++; return fn(name); }
  // Fallback générique amélioré
  fixed++;
  return `اكتشف وصفة ${name} التقليدية بمكوناتها الأصيلة وطريقة تحضيرها الشهية`;
});

fs.writeFileSync(HTML_PATH, html);
console.log(`✅ ${fixed} descriptions corrigées`);
